    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Muss ich alle Obstsorten meiden?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nein. Beeren, Zitrusfrüchte und Bananen werden meist gut vertragen (Glukose:Fructose-Verhältnis günstig). Apfel, Birne, Mango sind kritischer."
          }
        },
        {
          "@type": "Question",
          "name": "Was ist der Unterschied zur hereditären Fructose-Intoleranz (HFI)?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "HFI ist eine seltene, lebensbedrohliche Enzymdefekt-Erkrankung — strikter, lebenslanger Verzicht nötig. Intestinale Malabsorption ist häufig und meist gut managebar."
          }
        },
        {
          "@type": "Question",
          "name": "Hilft Glukose dabei, Fructose besser zu verdauen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Glukose unterstützt die Fructose-Resorption über den GLUT2-Transporter. Praktisch bedeutet das: Obst lieber zu Mahlzeiten mit Stärke essen, nicht solo."
          }
        },
        {
          "@type": "Question",
          "name": "Ist Honig erlaubt?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Honig hat ein ungünstiges Fructose:Glukose-Verhältnis (~1,2:1) und ist in der Karenzphase tabu. In der Toleranzphase einzeln testen — kleinere Mengen (≤ 1 TL) in Kombination mit Brot oft verträglich."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Fructose-Malabsorption (ICD E74.1) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Hat das was mit Reizdarm zu tun?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Bei vielen Reizdarm-Patient:innen findet sich begleitend eine Fructose-Malabsorption. Das Low-FODMAP-Konzept adressiert beide gleichzeitig."
          }
        }
      ]
    },
