      "mainEntity": [
        {
          "@type": "Question",
          "name": "Darf ich bei Gicht Hülsenfrüchte essen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Pflanzliche Purine (Bohnen, Linsen, Erbsen) erhöhen das Gicht-Risiko in großen Studien nicht. Tierische Purine sind das Problem."
          }
        },
        {
          "@type": "Question",
          "name": "Ist Bier wirklich so schlimm?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Bier enthält besonders viele Purine (auch alkoholfreies!). Schon 1 Bier/Tag erhöht das Gicht-Risiko deutlich. Wein in moderaten Mengen ist neutraler."
          }
        },
        {
          "@type": "Question",
          "name": "Helfen Kirschen wirklich?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Studien zeigen: 10–12 Kirschen täglich oder 1 Tasse Tart-Cherry-Juice senkt das Risiko akuter Anfälle. Effekt ähnlich wie bei manchen Medikamenten."
          }
        },
        {
          "@type": "Question",
          "name": "Wie viel Wasser pro Tag?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bei Gicht 2,5–3 Liter Wasser oder ungesüßter Tee. Verdünnt Harnsäure und unterstützt die renale Ausscheidung. Vorsicht bei eingeschränkter Herz- oder Nierenfunktion — vorher ärztlich abklären."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Hyperurikämie / Gicht (ICD E79.0 / M10) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Wie schnell wirkt Ernährung?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Erste Senkung der Harnsäure innerhalb von 2–4 Wochen. Volle Wirkung nach 2–3 Monaten."
          }
        }
      ]
