    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Muss ich auf alle Milchprodukte verzichten?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nein. Die meisten Betroffenen vertragen 5–12 g Laktose pro Mahlzeit. Hartkäse und Joghurt sind oft unproblematisch."
          }
        },
        {
          "@type": "Question",
          "name": "Wie sichere ich meine Kalzium-Versorgung?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Hartkäse, kalziumreiches Mineralwasser (> 400 mg/l), Brokkoli, Grünkohl, Mandeln, kalziumangereicherte Pflanzendrinks. Wir berechnen das in der Beratung individuell."
          }
        },
        {
          "@type": "Question",
          "name": "Was unterscheidet Laktose-Intoleranz von Milchallergie?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Allergie ist eine Immunreaktion gegen Milchproteine (selten, oft im Kindesalter). Laktose-Intoleranz ist ein Enzymmangel — kein Immungeschehen, keine schwere Reaktion."
          }
        },
        {
          "@type": "Question",
          "name": "Sind A2-Milchprodukte besser verträglich?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A2-Milch (nur A2-β-Casein) ist ein anderer Aspekt — sie hilft Menschen mit Casein-Empfindlichkeit, nicht der klassischen Laktose-Intoleranz. Bei Laktose-Intoleranz enthält A2-Milch genauso viel Laktose wie normale Milch — kein Vorteil."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Laktose-Intoleranz (ICD E73) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Sind Laktase-Tabletten sinnvoll?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja, für Ausnahme-Situationen (Restaurant, Urlaub). Für den Alltag ist die strukturierte Anpassung der Ernährung effektiver."
          }
        }
      ]
