      "mainEntityOfPage": {
        "@id": "https://rehab-five-nutrition-ernaehrungsberatung.com/wissen/osteoporose-ernaehrung.html#webpage"
      }
    },
    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Wie viel Kalzium brauche ich täglich?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bei Osteoporose 1000–1200 mg/Tag. Beispiel: 200 g Joghurt + 50 g Käse + 200 ml Mineralwasser (kalziumreich) decken etwa 1000 mg."
          }
        },
        {
          "@type": "Question",
          "name": "Reicht Sonnenlicht für Vitamin D?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In Mitteleuropa von Oktober bis April nicht — Supplementierung empfohlen (800–1000 IE/Tag). Im Sommer 15–20 Min Sonne (Gesicht/Arme) reichen oft."
          }
        },
        {
          "@type": "Question",
          "name": "Schadet zu viel Eiweiß den Knochen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nein — moderne Studien zeigen sogar, dass Eiweißmangel das größere Problem ist. 1,0–1,2 g/kg KG ist sicher und förderlich."
          }
        },
        {
          "@type": "Question",
          "name": "Vitamin K2 — was sagt die Studie?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Cockayne (2006) und Knapen (2013) zeigen: 180 µg MK-7/Tag verbessern Knochenmineraldichte und reduzieren Frakturrisiko. Wirkung bei kombinierter Gabe mit D3 verstärkt. Supplementierung sinnvoll bei niedrigem Natto- und Käse-Konsum."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Osteoporose (ICD M80–M82) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Welche Rolle spielt Bewegung?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sehr wichtig. Krafttraining (2× pro Woche) und Stoßbelastungen aktivieren den Knochenaufbau direkt — Ernährung allein reicht nicht."
          }
        }
      ]
    },
