      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Kann Ernährung PPI-Medikamente ersetzen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bei milder bis mittelschwerer GERD ja — Studien zeigen vergleichbare Effekte. Bei schwerer Refluxösophagitis oder Barrett-Ösophagus sollte die medikamentöse Therapie in Abstimmung mit der Ärztin / dem Arzt bestehen bleiben."
          }
        },
        {
          "@type": "Question",
          "name": "Welche Lebensmittel sind die häufigsten Trigger?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Schokolade, Pfefferminze, Alkohol, fetthaltige und frittierte Speisen, Kaffee, scharfe Gewürze. Individuell oft auch Tomaten und Zitrusfrüchte."
          }
        },
        {
          "@type": "Question",
          "name": "Wie lange dauert es, bis Ernährung wirkt?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Erste Verbesserungen oft schon in 1–2 Wochen. Volle Wirkung nach 6–8 Wochen konsequenter Umstellung."
          }
        },
        {
          "@type": "Question",
          "name": "Hilft Apfelessig wirklich?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Studienlage dünn bis ablehnend. Wissenschaftlich plausibel ist nur sehr verdünnter Essig vor fetthaltigen Mahlzeiten — bei akutem Sodbrennen aber meist kontraproduktiv. Mediterrane Kost zeigt deutlich bessere und belegte Wirkung."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Reflux (ICD K21) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Hilft Schlafposition?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Linke Seitenlage und leicht erhöhter Oberkörper reduzieren nächtliche Refluxepisoden signifikant."
          }
        }
      ]
