        },
        {
          "@type": "Question",
          "name": "Sorbit in Trockenfrüchten — welche Mengen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pflaumen 6–10 g/100 g, Aprikosen 5 g/100 g, Pfirsiche 1–2 g/100 g, Kirschen 1–2 g/100 g. Toleranz bei Intoleranten meist < 5 g/Tag — also schon 50 g Trockenpflaumen können Beschwerden auslösen."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Sorbit-Intoleranz (ICD E74.3) ist erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
