        {
          "@type": "Question",
          "name": "Kohlenhydrate vor dem Schlaf?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja, für intensive Trainings-Tage: 30–50 g langsame KH (Haferflocken, Vollkornbrot) + 30 g Casein-Eiweiß (Quark) vor dem Schlaf — füllt Glykogen, fördert Recovery. An Ruhetagen oder Diätphasen weglassen."
          }
        },
        {
          "@type": "Question",
          "name": "Brauche ich Supplements?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Wenige sind evidenzbasiert: Kreatin, Koffein, Beta-Alanin (für bestimmte Sportarten), Vitamin D, Eisen bei Mangel."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse die Beratung?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bei medizinischer Indikation (Verletzung, RED-S, etc.) ja. Reine Performance-Beratung ohne Diagnose meist privat."
          }
        }
