      "mainEntity": [
        {
          "@type": "Question",
          "name": "Helfen Soja und Phytoöstrogene wirklich bei Hitzewallungen?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "In Meta-Analysen zeigt Soja moderate Effekte (Reduktion um etwa 20 %). Konsequente tägliche Zufuhr nötig. Bei Brustkrebs-Vorgeschichte vorher ärztlich abklären."
          }
        },
        {
          "@type": "Question",
          "name": "Wie viel Eiweiß brauche ich in der Menopause?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "1,2 g/kg KG — also etwa 70–80 g pro Tag bei einer 60-kg-Frau. Verteilt auf 3–4 Mahlzeiten."
          }
        },
        {
          "@type": "Question",
          "name": "Warum nehme ich plötzlich zu?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Östrogenmangel verändert Fettverteilung (mehr Bauchfett), Grundumsatz sinkt, oft auch Muskelabbau. Lösung: weniger einfache Kohlenhydrate, mehr Eiweiß, Krafttraining."
          }
        },
        {
          "@type": "Question",
          "name": "Ist Soja sicher bei Brustkrebs-Risiko?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Messina (2016) und große Folgestudien zeigen: Moderater Soja-Konsum (1–2 Portionen/Tag) ist auch bei Brustkrebs-Vorgeschichte sicher und teils protektiv. Bei Tamoxifen-Therapie vor Beginn ärztlich abklären — vorsichtige Empfehlung."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Wechseljahre-Beschwerden (ICD N95) sind erstattungsfähig nach §43 SGB V — typisch 80%."
          }
        },
        {
          "@type": "Question",
          "name": "Was schützt vor Osteoporose?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Kalzium 1000 mg + Vitamin D 800 IE + Eiweiß 1,2 g/kg + Krafttraining 2× pro Woche. In Kombination am wirksamsten."
          }
        }
      ]
