    {
      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Was ist Zöliakie?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Zöliakie ist eine chronische Autoimmunerkrankung, bei der das Klebereiweiß Gluten (in Weizen, Roggen, Gerste, Dinkel) die Dünndarmschleimhaut schädigt. Folgen: Zottenatrophie, Mangelernährung. Diagnose über Antikörpertest (tTG-IgA, EMA) und Dünndarmbiopsie. Therapie: lebenslange, strikt glutenfreie Ernährung."
          }
        },
        {
          "@type": "Question",
          "name": "Was bedeutet ‚strikt glutenfrei'?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Glutengehalt < 20 mg/kg in fertigen Lebensmitteln (EU-Verordnung 41/2009). Auch geringste Mengen können Schleimhaut-Schäden auslösen. Wichtig sind Kennzeichnungs-Aufmerksamkeit, Vermeidung von Kreuzkontamination und Verzicht auf ‚Sauberkeitskompromisse' im Haushalt."
          }
        },
        {
          "@type": "Question",
          "name": "Welche Mikronährstoffe sind bei Zöliakie kritisch?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Zum Diagnose-Zeitpunkt oft Eisen, Vitamin B12, Folsäure, Vitamin D, Zink, Kalzium. Glutenfreie Fertigprodukte sind häufig nicht angereichert — strukturierte Substitution und regelmäßige Kontrollen sind wichtig."
          }
        },
        {
          "@type": "Question",
          "name": "Wie geht man mit Kreuzkontamination um?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Im glutenhaltigen Haushalt: getrennte Brettchen, Toaster, Butter (Brösel!), Backbleche. In der Gastronomie auf Zertifikate achten (z. B. ‚Glutenfrei'-Symbol DZG). Vorsicht bei Hafer — nur als ‚glutenfreier Hafer' geeignet."
          }
        },
        {
          "@type": "Question",
          "name": "Übernimmt die Krankenkasse die Ernährungsberatung?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ja. Zöliakie (ICD K90.0) ist eindeutig erstattungsfähig nach §43 SGB V. Die Erstattung liegt typischerweise bei 80%, einzelne Kassen sogar bis 100%. Eine ärztliche Notwendigkeitsbescheinigung ist Voraussetzung."
          }
        },
        {
          "@type": "Question",
          "name": "Was ist der Unterschied zu Glutensensitivität (NCWS)?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Bei Nicht-Zöliakie-Weizensensitivität (NCWS) fehlen Antikörper und Zottenatrophie. Symptome ähneln Zöliakie, treten aber meist milder auf. Strenge Karenz ist nicht zwingend — moderate Reduktion oft ausreichend. Vor jeder Karenz Zöliakie ärztlich ausschließen!"
          }
        }
      ]
    },
